import{z as p,x as E,o as s,c as A,q as o,j as n,D as t,d as l,s as i,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"偏序与格直觉","description":"","frontmatter":{"title":"偏序与格直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/poset-lattice.md","filePath":"cs/poset-lattice.md","lastUpdated":1791413859000}'),B={name:"cs/poset-lattice.md"};function m(c,a,h,u,D,f){const r=E("Mermaid");return s(),A("div",null,[a[2]||(a[2]=o('<h1 id="偏序与格直觉" tabindex="-1">偏序与格直觉 <a class="header-anchor" href="#偏序与格直觉" aria-label="Permalink to &quot;偏序与格直觉&quot;">​</a></h1><div class="epigraph"><p>可比才谈大小，不可比则并排；若任意两个元都有最小上界与最大下界，这张序就是格。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications 整理</footer></div><p>上一课<a href="/cs/equivalence-partition">等价关系与划分</a>钉死了对称的「同一类」。本课不重证划分对应，也不从「序数」另起。缺口是：后课 DAG、包含、布尔代数的 \\(x\\le y\\)，要的是<strong>反对称</strong>的比较，不是对称的可替换。集合课点过偏序，没有 Hasse、没有交并当运算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>等价把互相到达的元粘成一点。序要保留方向：\\(x\\le y\\) 且 \\(y\\le x\\) 则 \\(x=y\\)。缺口因此不是再造有序对，而是：自反、反对称、传递的关系叫做偏序；未必全序——可以有不可比的元。<span class="marginnote">三条性质翻译成大白话：自反是「自己不比自己小」；反对称是「若两个方向互相压不住，那它们就是同一个元」；传递是「A 在 B 前、B 在 C 前，则 A 必在 C 前」。三条合起来才配叫「序」，缺任何一条都会推出荒谬结论——比如缺反对称时，\\(x\\le y\\) 与 \\(y\\le x\\) 可同时成立而 \\(x\\ne y\\)，方向感就全乱了。</span>Hasse 图去掉自反与可传递推得的边，只留覆盖关系。</p><p>若任意 \\(x,y\\) 都有上确界 \\(x\\vee y\\) 与下确界 \\(x\\wedge y\\)，偏序集是<strong>格</strong>。幂集用 \\(\\subseteq\\)，交并就是确界：这把<a href="/cs/boolean-algebra">布尔代数</a>解释成某集合的幂集格，本课只要这个对照，不把门电路请回来。</p><h3 id="偏序不是拓扑排序本身" tabindex="-1">偏序不是拓扑排序本身 <a class="header-anchor" href="#偏序不是拓扑排序本身" aria-label="Permalink to &quot;偏序不是拓扑排序本身&quot;">​</a></h3><p>拓扑序是把偏序<strong>扩展</strong>成全序（若无环）。本课对象还没有「图上的边当序」；那是 DAG 课。把 Hasse 当成算法流程图，后课会把覆盖与可达混名。</p><p><span class="marginnote">Rosen 用整除偏序与幂集格当主例。整除：\\(\\mathrm{lcm}\\) 与 \\(\\gcd\\) 是并与交。布尔格的互补律对应上一课程的 \\(\\bar x\\)。函数与可数下一课才要单射满射。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检查三性质。画 Hasse：底小顶大（或反过来，声明即可）。求两元的公共上界中的最小者；不存在则不是格（例如缺了某并）。全序是任意两元可比的偏序。</p>',11)),(s(),n(d,null,{default:t(()=>[i(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EQ%5B%22%E7%AD%89%E4%BB%B7%EF%BC%9A%E5%AF%B9%E7%A7%B0%22%5D%20--%3E%20PO%5B%22%E5%81%8F%E5%BA%8F%EF%BC%9A%E5%8F%8D%E5%AF%B9%E7%A7%B0%22%5D%0A%20%20PO%20--%3E%20HASSE%5B%22Hasse%20%E8%A6%86%E7%9B%96%22%5D%0A%20%20PO%20--%3E%20LAT%5B%22%E6%A0%BC%EF%BC%9A%E4%BB%BB%E6%84%8F%E4%B8%A4%E5%85%83%E6%9C%89%E4%BA%A4%E5%B9%B6%22%5D%0A%20%20LAT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%87%BD%E6%95%B0%E4%B8%8E%E5%8F%AF%E6%95%B0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"常见误区：Hasse 图上没有画出的边并非不存在。按约定它省掉了自反边（每个点到自己）和传递边（能顺着折线走到的就不画）。初学者照图逐条数边会得出「\\(1\\) 与 \\(4\\) 没关系」的错误结论——读 Hasse 图要问「是否可达」，不是「是否有线直连」。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"后课类型包含、文件系统目录（若当包含则要小心循环挂载）、知识树本身，都是偏序直觉。格给「最小公共超类型 / 最大公共子类型」一句话：那是 \\(\\vee\\)/\\(\\wedge\\)。本课不把格论定理（模格、分配格分类）写进主干；分配性已在布尔公理里用过。",-1)),a[6]||(a[6]=e("p",null,"划分的细化按「更细」构成偏序，上一课末句留下的缺口在这里落地：等价关系按包含也成偏序，一般不是全序。",-1)),a[7]||(a[7]=e("p",null,"数字实例最能钉住「格」：取 \\(12\\) 的全部因子按整除排序，这就是一张格。",-1)),(s(),n(d,null,{default:t(()=>[i(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20B1%5B%221%22%5D%20--%3E%20D2%5B%222%22%5D%0A%20%20B1%20--%3E%20D3%5B%223%22%5D%0A%20%20D2%20--%3E%20S4%5B%224%22%5D%0A%20%20D2%20--%3E%20S6%5B%226%22%5D%0A%20%20D3%20--%3E%20S6%0A%20%20S4%20--%3E%20T%5B%2212%22%5D%0A%20%20S6%20--%3E%20T%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<p><span class="marginnote">在这张图上验证：\\(4\\) 与 \\(6\\) 不可比（谁也不整除谁），但它们的最小公共上界是 \\(12\\)（即 \\(\\mathrm{lcm}\\)），最大公共下界是 \\(2\\)（即 \\(\\gcd\\)）。任意两元都找得到这两个「汇合点」，所以整除序是格；把 \\(12\\) 换成 \\(6\\)，因子 \\(\\{1,2,3,6\\}\\) 依然成格。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入良基关系上的超限归纳——归纳再下一课才从 \\(\\mathbb{N}\\) 开始。也不把偏函数、单调函数当重点；函数作为右唯一关系是下一课。电路时序的状态图是有向图，未必是偏序（有环就不是）。</p><p>后课默认：谈到 \\(\\le\\)、包含、整除，先问是否偏序、是否格。编号与双射另说。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>偏序是自反、反对称、传递；允许不可比。</li><li>格要求任意两元有上、下确界；幂集是标准例子。</li><li>下一课把关系收成函数，并谈可数。</li><li>出处：Rosen, <em>Discrete Mathematics and Its Applications</em>。</li></ul>',6))])}const g=p(B,[["render",m]]);export{b as __pageData,g as default};
